sql.where:
homepage_id = #{homepage_id}

	AND	${search_type} LIKE '%'||#{search_text}||'%'


	AND	course_id = #{searching_course_id}




	AND	request_start_date > TO_CHAR(SYSDATE, 'yyyy-MM-dd')


	AND	request_start_date <= TO_CHAR(SYSDATE, 'yyyy-MM-dd')
	AND request_end_date >= TO_CHAR(SYSDATE, 'yyyy-MM-dd')


	AND	request_end_date < TO_CHAR(SYSDATE, 'yyyy-MM-dd')




	AND	edu_start_date > TO_CHAR(SYSDATE, 'yyyy-MM-dd')


	AND	edu_start_date <= TO_CHAR(SYSDATE, 'yyyy-MM-dd')
	AND edu_end_date >= TO_CHAR(SYSDATE, 'yyyy-MM-dd')


	AND	edu_end_date < TO_CHAR(SYSDATE, 'yyyy-MM-dd')




	AND	request_type = #{searching_request_type}


	AND	request_end_date >= #{start_period}


	AND	request_start_date <= #{end_period}

mapper.select:
${pagingTop}
SELECT

FROM
	LECTURE_INFO

ORDER BY lecture_id DESC
${pagingBottom}

${pagingTop} SELECT
FROM LECTURE_INFO
AND course_id = ( SELECT course_id FROM (SELECT rownum, course_id FROM course_info WHERE VIEW_START_DATE <= SYSDATE AND VIEW_END_DATE >= SYSDATE AND use_yn = 'Y' AND rownum = 1) ) ORDER BY lecture_id DESC ${pagingBottom}

${pagingTop} SELECT
CASE WHEN (SELECT COUNT(*) FROM LECTURE_REQUEST C WHERE (C.request_type = '온라인') AND C.lecture_id = i.lecture_id AND C.request_status NOT IN('예약취소')) >= (online_person_count + wait_person_count) THEN '정원마감' WHEN (SELECT COUNT(*) FROM LECTURE_REQUEST C WHERE C.request_status = '추첨대기' AND C.lecture_id = i.lecture_id) >= (wait_person_count) AND i.request_type = '추첨제' THEN '모집마감' WHEN TO_DATE(request_start_date, 'yyyy-mm-dd') > TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '모집예정' WHEN TO_DATE(request_start_date, 'yyyy-mm-dd') <= TO_DATE(SYSDATE, 'yyyy-mm-dd') AND TO_DATE(request_end_date, 'yyyy-mm-dd') >= TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '모집중' WHEN TO_DATE(request_end_date, 'yyyy-mm-dd') < TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '모집마감' END AS lecture_status1, CASE WHEN TO_DATE(edu_start_date, 'yyyy-mm-dd') > TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '교육대기' WHEN TO_DATE(edu_start_date, 'yyyy-mm-dd') <= TO_DATE(SYSDATE, 'yyyy-mm-dd') AND TO_DATE(edu_end_date, 'yyyy-mm-dd') >= TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '교육중' WHEN TO_DATE(edu_end_date, 'yyyy-mm-dd') < TO_DATE(SYSDATE, 'yyyy-mm-dd') THEN '교육마감' END AS lecture_status2, (SELECT COUNT(*) FROM LECTURE_REQUEST C WHERE C.request_type = '온라인' AND C.request_status = '예약완료' AND C.lecture_id = i.lecture_id) AS online_request_count, (SELECT COUNT(*) FROM LECTURE_REQUEST C WHERE C.request_type = '오프라인' AND C.request_status = '예약완료' AND C.lecture_id = i.lecture_id) AS offline_request_count, (SELECT COUNT(*) FROM LECTURE_REQUEST C WHERE C.request_status IN ('예약대기', '추첨대기') AND C.lecture_id = i.lecture_id) AS wait_request_count, ROW_NUMBER() OVER (ORDER BY i.lecture_id) AS reverse_rownum, i.homepage_id, course_id,i.lecture_id,lecture_title, edu_start_date,edu_end_date,edu_start_time,edu_end_time,request_start_date,request_end_date,edu_school, online_person_count,offline_person_count,wait_person_count,i.request_type,teacher_name,teacher_tel,supporter_name, supporter_tel,edu_school_map,lecture_content,i.add_date,i.add_ip,i.add_id,edu_address_1,edu_address_2,teacher_id, day_week,edu_second_school,r.request_status,r.add_date AS request_add_date,r.request_id
FROM LECTURE_INFO AS i INNER JOIN LECTURE_REQUEST AS r ON i.LECTURE_ID = r.LECTURE_ID WHERE i.homepage_id = #{homepage_id} AND r.add_id = #{request_add_id} AND r.request_status NOT IN('예약취소') ORDER BY r.REQUEST_ID DESC ${pagingBottom}

mapper.delete:
DELETE
	LECTURE_INFO
WHERE
	homepage_id = #{homepage_id}
  AND lecture_id = #{lecture_id}
